```typescript
export const DUMMY_ADMIN = {
  email: 'admin@example.com',
  password: 'password123',
  name: '관리자'
}

export function validateCredentials(email: string, password: string): boolean {
  return email === DUMMY_ADMIN.email && password === DUMMY_ADMIN.password
}

export async function dummyLogin(email: string, password: string): Promise<{
  success: boolean
  message: string
}> {
  await new Promise(resolve => setTimeout(resolve, 500))

  const isValid = validateCredentials(email, password)

  if (isValid) {
    if (typeof window !== 'undefined') {
      localStorage.setItem('dummy-auth', 'true')
    }
    return { success: true, message: '로그인 성공' }
  }

  return { success: false, message: '이메일 또는 비밀번호가 올바르지 않습니다' }
}

export function dummyLogout() {
  if (typeof window !== 'undefined') {
    localStorage.removeItem('dummy-auth')
  }
}

export function isDummyAuthenticated(): boolean {
  if (typeof window === 'undefined') return false
  return localStorage.getItem('dummy-auth') === 'true'
}
```

2단계: LoginForm 리팩토링 (src/components/login-form.tsx)
```typescript
'use client'

import { useState } from 'react'
import { useRouter } from 'next/navigation'
import { useForm } from 'react-hook-form'
import { zodResolver } from '@hookform/resolvers/zod'
import { toast } from 'sonner'
import { EyeIcon, EyeOffIcon } from 'lucide-react'

import { Button } from '@/components/ui/button'
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/card'
import { Form, FormControl, FormField, FormItem, FormLabel, FormMessage } from '@/components/ui/form'
import { Input } from '@/components/ui/input'
import { loginSchema, type LoginFormData } from '@/lib/validations/auth'
import { dummyLogin } from '@/lib/auth-dummy'

export function LoginForm() {
  const router = useRouter()
  const [showPassword, setShowPassword] = useState(false)
  const [isLoading, setIsLoading] = useState(false)

  const form = useForm<LoginFormData>({
    resolver: zodResolver(loginSchema),
    defaultValues: {
      email: '',
      password: ''
    }
  })

  const onSubmit = async (data: LoginFormData) => {
    setIsLoading(true)
    try {
      const result = await dummyLogin(data.email, data.password)

      if (result.success) {
        toast.success(result.message)
        router.push('/admin/dashboard')
      } else {
        toast.error(result.message)
      }
    } catch (error) {
      toast.error('로그인 중 오류가 발생했습니다')
    } finally {
      setIsLoading(false)
    }
  }

  return (
    <Card className="mx-auto w-full max-w-md">
      <CardHeader className="space-y-1">
        <CardTitle className="text-center text-2xl font-bold">로그인</CardTitle>
        <CardDescription className="text-center">
          관리자 계정으로 로그인하세요
        </CardDescription>
      </CardHeader>
      <CardContent>
        <Form {...form}>
          <form onSubmit={form.handleSubmit(onSubmit)} className="space-y-4">
            <FormField
              control={form.control}
              name="email"
              render={({ field }) => (
                <FormItem>
                  <FormLabel>이메일</FormLabel>
                  <FormControl>
                    <Input
                      type="email"
                      placeholder="admin@example.com"
                      {...field}
                    />
                  </FormControl>
                  <FormMessage />
                </FormItem>
              )}
            />

            <FormField
              control={form.control}
              name="password"
              render={({ field }) => (
                <FormItem>
                  <FormLabel>비밀번호</FormLabel>
                  <FormControl>
                    <div className="relative">
                      <Input
                        type={showPassword ? 'text' : 'password'}
                        placeholder="비밀번호를 입력하세요"
                        className="pr-10"
                        {...field}
                      />
                      <Button
                        type="button"
                        variant="ghost"
                        size="icon"
                        className="absolute top-0 right-0 h-full px-3"
                        onClick={() => setShowPassword(!showPassword)}
                      >
                        {showPassword ? <EyeOffIcon className="h-4 w-4" /> : <EyeIcon className="h-4 w-4" />}
                      </Button>
                    </div>
                  </FormControl>
                  <FormMessage />
                </FormItem>
              )}
            />

            <Button type="submit" className="w-full" disabled={isLoading}>
              {isLoading ? '로그인 중...' : '로그인하기'}
            </Button>
          </form>
        </Form>

        <div className="mt-6 text-center">
          <p className="text-muted-foreground text-sm">
            테스트 계정: admin@example.com / password123
          </p>
        </div>
      </CardContent>
    </Card>
  )
}
```
